<?php
return function(PDO $pdo): void {
 $sql = [
 "CREATE TABLE IF NOT EXISTS site_settings (`setting_key` VARCHAR(100) PRIMARY KEY, `setting_value` TEXT NULL, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
 "CREATE TABLE IF NOT EXISTS services (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, slug VARCHAR(100) NOT NULL UNIQUE, name VARCHAR(160) NOT NULL, category VARCHAR(100) NOT NULL, image VARCHAR(500) NOT NULL, description TEXT NOT NULL, inclusions JSON NULL, sort_order INT NOT NULL DEFAULT 0, is_active TINYINT(1) NOT NULL DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
 "CREATE TABLE IF NOT EXISTS portfolio_photos (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, title VARCHAR(200) NOT NULL, category VARCHAR(100) NOT NULL, image VARCHAR(500) NOT NULL, thumbnail VARCHAR(500) NULL, featured TINYINT(1) NOT NULL DEFAULT 0, aspect_ratio VARCHAR(30) NULL, is_placeholder TINYINT(1) NOT NULL DEFAULT 0, sort_order INT NOT NULL DEFAULT 0, is_active TINYINT(1) NOT NULL DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX idx_portfolio_category(category), INDEX idx_portfolio_featured(featured)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
 "CREATE TABLE IF NOT EXISTS testimonials (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, customer_name VARCHAR(160) NOT NULL, category VARCHAR(100) NOT NULL, review TEXT NOT NULL, is_sample TINYINT(1) NOT NULL DEFAULT 1, is_active TINYINT(1) NOT NULL DEFAULT 1, sort_order INT NOT NULL DEFAULT 0) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
 "CREATE TABLE IF NOT EXISTS bookings (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, customer_name VARCHAR(160) NOT NULL, phone VARCHAR(25) NOT NULL, email VARCHAR(190) NULL, event_type VARCHAR(100) NOT NULL, event_date DATE NULL, event_location VARCHAR(255) NULL, package_name VARCHAR(160) NULL, message TEXT NULL, status VARCHAR(30) NOT NULL DEFAULT 'new', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX idx_bookings_created(created_at), INDEX idx_bookings_status(status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4"
 ]; foreach($sql as $statement)$pdo->exec($statement);
};
